structural.css:
.board {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  padding: 12px;
  border: 2px solid var(--line-strong);
  border-radius: var(--radius-xl);
  background: var(--sunken);
  box-sizing: border-box;
  width: 100%;
  /* BOARD_MAX_SIZE is 420 on device; 330 fits 390 minus the gutters. */
  max-width: 330px;
  aspect-ratio: 1 / 1;
  margin: 0 auto;
}
.cell {
  display: grid;
  place-items: center;
  border-radius: var(--radius-lg);
  background: var(--surface);
  box-shadow: var(--shadow-sm);
  font-size: 64px;
  line-height: 1;
  font-weight: 800;
  letter-spacing: -0.04em;
}
.cell--win { background: color-mix(in srgb, var(--mark-win) 18%, var(--surface)); }
